    Dimension(int filas, int columnas) : filas_{filas}, columnas_{columnas} {}

    int filas() const {
        return filas_;
    }

    int columnas() const {
        return columnas_;
    }

    void cambiar_a(int filas, int columnas) {
        filas_ = filas;
        columnas_ = columnas;
    }

private:
    int filas_;
    int columnas_;
};

int main() {
    const Dimension fija{2, 5};
    Dimension original{1, 3};
    const Dimension copia = original;

    original.cambiar_a(4, 2);

    std::cout << fija.filas() << "x" << fija.columnas() << "\n";
    std::cout << copia.filas() << "x" << copia.columnas() << " " << original.filas() << "x" << original.columnas();

